arguments.command:
# Try common dev ports
@(5000, 5001, 5139, 5140, 7000, 7001, 8080, 8081, 3000) | ForEach-Object {
    try { 
        $r = Invoke-WebRequest -Uri "http://localhost:$_/api/feed" -Method GET -TimeoutSec 2 -ErrorAction Stop
        "Port $_`: $($r.StatusCode)"
    } catch { }
}
"Done checking ports"

